    labels=['Raw TP']+[f'V{r["version"]}: '+('no block unaries' if r['version']==1 else 'block unaries') for r in rs]
    vals=[rs[0]['raw']['biological_miou']]+[r['wcsp']['biological_miou'] for r in rs]
    f,(ax,delta_ax)=plt.subplots(1,2,figsize=(11,4),gridspec_kw={'width_ratios':[1.35,1]});bars=ax.bar(labels,vals,color=['#8394a1','#326899','#18a18b'][:len(vals)])
    ax.set_ylim(0,min(1,max(vals)*1.22));ax.set_ylabel('Pooled biological mIoU');ax.set_title('100 full PanNuke patches - paired comparison')
    for b,v in zip(bars,vals):ax.text(b.get_x()+b.get_width()/2,v+.005,f'{v:.4f}',ha='center')
    for j,r in enumerate(rs):
        d=100*r['delta'];lo,hi=[100*x for x in r['ci95']]
        delta_ax.errorbar(d,j,xerr=[[d-lo],[hi-d]],fmt='o',capsize=5,color=['#326899','#18a18b'][j])
    delta_ax.axvline(0,color='#8394a1',linestyle='--');delta_ax.set_yticks(range(len(rs)),[f'Version {r["version"]}' for r in rs]);delta_ax.set_xlabel('Change vs raw (percentage points)');delta_ax.set_title('Paired 95% patch-bootstrap interval');delta_ax.set_ylim(-.6,len(rs)-.4)
    f.tight_layout();f.savefig(figdir/'overall.png',dpi=180);plt.close(f)
    f,ax=plt.subplots(figsize=(10,4));x=np.arange(6);width=.8/len(labels)
    for j,(name,m) in enumerate(zip(labels,[rs[0]['raw']]+[r['wcsp'] for r in rs])):ax.bar(x+(j-(len(labels)-1)/2)*width,m['iou'],width,label=name)
    ax.set_xticks(x,NAMES,rotation=15);ax.set_ylabel('Pooled IoU');ax.set_ylim(0,1);ax.legend(fontsize=9);f.tight_layout();f.savefig(figdir/'per_class.png',dpi=180);plt.close(f)
    f,ax=plt.subplots(figsize=(8,4));x=np.arange(len(rs));w=.25
