    ordered=sorted(rs[-1]['patches'],key=lambda p:p['wcsp']['biological_miou']-p['raw']['biological_miou'])
    examples={}
    for kind,p in [('largest_gain',ordered[-1]),('largest_loss',ordered[0]),('representative',ordered[len(ordered)//2])]:
        i=p['image_index'];examples[kind]=dict(image_index=i,tissue=p['tissue'],delta=p['wcsp']['biological_miou']-p['raw']['biological_miou'])
        a=np.load(HERE/f'version_1/patch_{i:04d}.npz');images=[np.load(HERE/f'cache/rgb_{i:04d}.npy'),a['gt'],a['raw']];titles=['H&E','Ground truth',f'Raw TP\nmIoU {p["raw"]["biological_miou"]:.3f}']
        for r in rs:
            b=np.load(HERE/f'version_{r["version"]}/patch_{i:04d}.npz');images.append(b['pred']);record=next(x for x in r['patches'] if x['image_index']==i);titles.append(f'Version {r["version"]}\nmIoU {record["wcsp"]["biological_miou"]:.3f}')
        f,axs=plt.subplots(1,len(images),figsize=(14,4))
